source('mp10_hypothesis_followup_v1/scripts/common.R')
# Preserve historical tables with unambiguous provenance.
names<-c('candidate_de_effects.tsv','candidate_dataset_paired_descriptive.tsv','candidate_sensitivity_effects.tsv','candidate_single_specimen_influence.tsv','epi_existing_cluster_composition.tsv','epi_existing_cluster_coverage.tsv','epi_quality_paired.tsv','epi_score_quality_correlations.tsv','epi_within_cluster_candidate_changes.tsv','patient_relationship_audit.tsv','abundance_associations.tsv','axis_evidence_comparison.tsv','scenic_second_seed_coverage.tsv')
for(n in names){d<-old(n);d[,source_path:=file.path(OLD,'tables',n)];put(d,paste0('reused_',n))}
sc<-rd('sample_level_scores.tsv.gz');uni<-rd('scoring_gene_universe.tsv.gz')[family=='Epi_all',gene];sr<-rd('signature_registry.tsv');hm<-fread(file.path(REF,'hallmark.tsv.gz'));mt<-hm[gs_name=='HALLMARK_MTORC1_SIGNALING',unique(gene_symbol)];sets<-list(MP10=M20,mTORC1=mt)
for(resource in c('collectri','dorothea_AB')){n<-fread(file.path(REF,paste0(resource,'.tsv')));for(tf in c('SREBF1','SREBF2'))sets[[paste(resource,tf,sep='_')]]<-n[source==tf,unique(target)]}
sn<-old('scenic_Epi_regulon_edges.tsv.gz');if(all(c('TF','target')%in%names(sn)))for(tf in c('SREBF1','SREBF2'))sets[[paste('SCENIC',tf,sep='_')]]<-sn[TF==tf,unique(target)]
gene<-rbindlist(lapply(names(sets),function(n)data.table(signature=n,gene=sets[[n]],in_MP10=sets[[n]]%in%M20,in_mTORC1=sets[[n]]%in%mt,in_new_Epi_universe=sets[[n]]%in%uni)));put(gene,'regulatory_gene_membership.tsv.gz');pairs<-CJ(set1=names(sets),set2=names(sets));pairs[,`:=`(n_shared=mapply(function(a,b)length(intersect(sets[[a]],sets[[b]])),set1,set2),shared_genes=mapply(function(a,b)paste(sort(intersect(sets[[a]],sets[[b]])),collapse=';'),set1,set2))];pairs[,evaluable:=lengths(sets)[set1]>0 & lengths(sets)[set2]>0];pairs[evaluable==FALSE,`:=`(n_shared=NA_integer_,shared_genes=NA_character_)];pairs[,reason:=ifelse(evaluable,'','missing_regulon_not_zero_target_set')];put(pairs,'gene_overlap.tsv')
plan<-old('model_plan.tsv');gs<-rd('gsea_results_repaired.tsv.gz');focus<-gs[pathway%in%paste0('HALLMARK_',c('MTORC1_SIGNALING','OXIDATIVE_PHOSPHORYLATION','G2M_CHECKPOINT','MYC_TARGETS_V1','TNFA_SIGNALING_VIA_NFKB','ANGIOGENESIS'))];focus<-merge(focus,plan,by='model_id');put(focus,'reused_repaired_focused_gsea.tsv.gz')
le<-focus[kind=='Epi'&pathway=='HALLMARK_MTORC1_SIGNALING'&primary==TRUE];le<-le[,.(gene=unlist(strsplit(leadingEdge,';',fixed=TRUE))),by=.(model_id,mask,NES,padj)];le[,in_MP10:=gene%in%M20];de<-rbindlist(lapply(unique(le$model_id),function(id){d<-old(paste0('de/',id,'.tsv.gz'));d[,model_id:=id];d}),fill=TRUE);put(merge(le,de,by=c('model_id','gene')),'Epi_mTORC1_driver_genes.tsv.gz')
# Full source clinical fields, summarized only; no clinical covariate is selected by effects.
md<-old('source_cell_metadata.tsv.gz');ac<-old('analysis_cell_metadata.tsv.gz');cc<-merge(ac[,.(barcode,sample_uid,dataset)],md[,.(barcode,T_stage,N_stage,M_stage,Type)],by='barcode');cl<-cc[,lapply(.SD,function(v)paste(sort(unique(na.omit(v))),collapse=';')),by=.(sample_uid,dataset),.SDcols=c('T_stage','N_stage','M_stage','Type')];put(cl,'clinical_field_audit.tsv')
# No reliability evidence for clinical fields beyond source cell metadata is available.
put(data.table(module='clinical_sensitivity',status='completed',reason='conditional recorded MIBC/NMIBC Type sensitivity; source-consistent 40/40, within-dataset variation in 3 datasets; T-stage missing14/40 not imputed; see clinical_addendum1.yaml'),'clinical_model_status.tsv')
res<-rd('model_results.tsv.gz');base<-res[setting=='main'];stab<-res[role=='sensitivity'];stab[,base_family:=sub('__.*$','',FDR_family)];base[,base_family:=FDR_family];join<-merge(stab,base[,.(base_family,x_base=x,y,celltype,cohort,beta_main=beta,q_main=q,status_main=status,model_main=model_id)],by=c('base_family','y','celltype','cohort'),allow.cartesian=TRUE);join<-join[x==x_base|(x=='MP10_Q95'&x_base=='MP10_Q50')];join[,interpretation:=fcase(status!='completed','not_evaluable',!is.finite(beta_main),'main_not_evaluable',beta*beta_main<0,'direction_reversed',abs(beta)<.25*abs(beta_main),'effect_near_zero_relative_to_main',default='direction_retained')];put(join,'sensitivity_comparison.tsv.gz')
# Profile coverage includes explicit absence, distinct from measured zero expression.
pr<-rd('coverage.tsv.gz');pr<-pr[,setdiff(names(pr),c('profile_present','eligibility_50','eligibility_30','absence_semantics','source_dataset','source_patient_unit','patient_id_status')),with=FALSE];q<-old('specimen_exposure_eligibility.tsv');types<-c('Epi_all','L50','H50','H10','H05','Treg','Treg_NC','Treg_CY','Tfh/CXCL13-like','Capillary EC','Arterial EC');grid<-CJ(sample_uid=q$sample_uid,profile_type=types);cover<-merge(grid,pr,by=c('sample_uid','profile_type'),all.x=TRUE);cover[,profile_present:=!is.na(profile_id)];cover[profile_present==FALSE,n_cells:=0];cover[,eligibility_50:=ifelse(n_cells>=50,'eligible','below50_or_absent')];cover[,eligibility_30:=ifelse(n_cells>=30,'eligible','below30_or_absent')];cover[,absence_semantics:=ifelse(profile_present,'measured_profile','no_profile; expression NA, cell count zero')];cover<-merge(cover,q[,.(sample_uid,source_dataset=dataset,source_patient_unit=patient_uid_recorded,patient_id_status)],by='sample_uid');cover[is.na(dataset),dataset:=source_dataset];cover[is.na(patient_uid_recorded),patient_uid_recorded:=source_patient_unit];for(n in c('main_patient','replacement_patient','Q50','Q95','Q50_z','Q95_z'))cover[is.na(get(n)),(n):=q[[n]][match(sample_uid,q$sample_uid)]];put(cover,'coverage.tsv.gz')
put(cover[main_patient==TRUE,.(n_specimens50=sum(n_cells>=50),n_specimens30=sum(n_cells>=30),n_recorded_units50=uniqueN(patient_uid_recorded[n_cells>=50]),n_datasets50=uniqueN(dataset[n_cells>=50])),by=profile_type],'coverage_summary.tsv');cat('INTEGRATION COMPLETE\n')
